"""LRU cache with per-entry time-to-live (TTL)."""

from collections import OrderedDict
import time


class TTLCache:
    """A least-recently-used cache whose entries may carry a lifetime.

    Entries stored without a TTL never expire. An entry stored at time ``t``
    with lifetime ``ttl`` is expired once ``clock() >= t + ttl``.
    """

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._clock = clock
        # Ordered least-recently-used -> most-recently-used.
        # Maps key -> (value, expires_at) where expires_at is None for no expiry.
        self._entries = OrderedDict()

    # -- internal helpers -------------------------------------------------

    def _expired(self, expires_at, now=None):
        return expires_at is not None and (self._clock() if now is None else now) >= expires_at

    def _purge_expired(self):
        now = self._clock()
        expired = [
            key
            for key, (_, expires_at) in self._entries.items()
            if self._expired(expires_at, now)
        ]
        for key in expired:
            del self._entries[key]
        return len(expired)

    # -- public API -------------------------------------------------------

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        expires_at = None if ttl is None else self._clock() + ttl
        if key in self._entries:
            # Replacing an existing key: restart its lifetime and recency.
            del self._entries[key]
        elif len(self._entries) >= self._capacity:
            # New key over capacity: drop expired entries first, then LRU.
            self._purge_expired()
            while len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        self._entries[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        value, expires_at = entry
        if self._expired(expires_at):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key)
        return entry is not None and not self._expired(entry[1])

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries)

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator: hand-written tokenizer + recursive-descent parser."""

import re


class _Tok:
    def __init__(self, kind, value):
        self.kind = kind
        self.value = value

    def __repr__(self):  # pragma: no cover - debugging aid
        return "%s(%r)" % (self.kind, self.value)


_TOKEN_RE = re.compile(
    r"""
    (?P<ws>\s+)
  | (?P<num>\d+\.\d+|\d+|\.\d+)
  | (?P<name>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op>\*\*|//|[+\-*/%()])
    """,
    re.VERBOSE,
)


def _tokenize(text):
    tokens = []
    pos = 0
    n = len(text)
    while pos < n:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            raise ValueError("unexpected character %r at position %d" % (text[pos], pos))
        pos = match.end()
        if match.lastgroup == "ws":
            continue
        if match.lastgroup == "num":
            lexeme = match.group("num")
            if "." in lexeme:
                tokens.append(_Tok("num", float(lexeme)))
            else:
                tokens.append(_Tok("num", int(lexeme)))
        elif match.lastgroup == "name":
            tokens.append(_Tok("name", match.group("name")))
        else:
            lexeme = match.group("op")
            if lexeme == "(":
                tokens.append(_Tok("lparen", lexeme))
            elif lexeme == ")":
                tokens.append(_Tok("rparen", lexeme))
            else:
                tokens.append(_Tok("op", lexeme))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.index = 0

    def peek(self):
        if self.index < len(self.tokens):
            return self.tokens[self.index]
        return None

    def take(self):
        token = self.peek()
        if token is not None:
            self.index += 1
        return token

    def expect(self, kind):
        token = self.take()
        if token is None or token.kind != kind:
            raise ValueError("expected %s" % kind)
        return token

    def parse_expression(self):
        value = self.parse_term()
        while True:
            token = self.peek()
            if token is None or token.kind != "op" or token.value not in ("+", "-"):
                return value
            self.take()
            rhs = self.parse_term()
            value = value + rhs if token.value == "+" else value - rhs

    def parse_term(self):
        value = self.parse_unary()
        while True:
            token = self.peek()
            if token is None or token.kind != "op":
                return value
            op = token.value
            if op == "*":
                self.take()
                value = value * self.parse_unary()
            elif op == "/":
                self.take()
                value = value / self.parse_unary()
            elif op == "//":
                self.take()
                value = value // self.parse_unary()
            elif op == "%":
                self.take()
                value = value % self.parse_unary()
            else:
                return value

    def parse_unary(self):
        token = self.peek()
        if token is not None and token.kind == "op" and token.value in ("+", "-"):
            self.take()
            operand = self.parse_unary()
            return operand if token.value == "+" else -operand
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        token = self.peek()
        if token is not None and token.kind == "op" and token.value == "**":
            self.take()
            exponent = self.parse_unary()  # right-associative, binds looser than unary
            return base ** exponent
        return base

    def parse_primary(self):
        token = self.take()
        if token is None:
            raise ValueError("missing operand")
        if token.kind == "num":
            return token.value
        if token.kind == "lparen":
            value = self.parse_expression()
            self.expect("rparen")
            return value
        if token.kind == "name":
            name = token.value
            if name not in ("min", "max", "abs"):
                raise ValueError("unknown name %r" % name)
            self.expect("lparen")
            args = [self.parse_expression()]
            while True:
                nxt = self.peek()
                if nxt is not None and nxt.kind == "op" and nxt.value == ",":
                    self.take()
                    args.append(self.parse_expression())
                    continue
                break
            self.expect("rparen")
            if name == "abs":
                if len(args) != 1:
                    raise ValueError("abs() takes exactly one argument")
                return abs(args[0])
            if len(args) < 1:
                raise ValueError("%s() takes at least one argument" % name)
            return min(args) if name == "min" else max(args)
        raise ValueError("unexpected token %r" % (token.value,))


def evaluate(text):
    """Parse and evaluate an arithmetic expression, returning an int or float."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    tokens = _tokenize(text)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    result = parser.parse_expression()
    if parser.peek() is not None:
        raise ValueError("unexpected trailing token %r" % (parser.peek().value,))
    return result

